pub struct PropertyBuilder<'a: 'b, 'b, A: flatbuffers::Allocator + 'a> {
  fbb_: &'b mut flatbuffers::FlatBufferBuilder<'a, A>,
  start_: flatbuffers::WIPOffset<flatbuffers::TableUnfinishedWIPOffset>,
}
impl<'a: 'b, 'b, A: flatbuffers::Allocator + 'a> PropertyBuilder<'a, 'b, A> {
  #[inline]
  pub fn add_key(&mut self, key: flatbuffers::WIPOffset<&'b  str>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(Property::VT_KEY, key);
  }
  #[inline]
  pub fn add_kind(&mut self, kind: ValueKind) {
    self.fbb_.push_slot::<ValueKind>(Property::VT_KIND, kind, ValueKind::String);
  }
  #[inline]
  pub fn add_s(&mut self, s: flatbuffers::WIPOffset<&'b  str>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<_>>(Property::VT_S, s);
  }
  #[inline]
  pub fn add_i(&mut self, i: i64) {
    self.fbb_.push_slot::<i64>(Property::VT_I, i, 0);
  }
  #[inline]
  pub fn add_d(&mut self, d: f64) {
    self.fbb_.push_slot::<f64>(Property::VT_D, d, 0.0);
  }
  #[inline]
  pub fn new(_fbb: &'b mut flatbuffers::FlatBufferBuilder<'a, A>) -> PropertyBuilder<'a, 'b, A> {
    let start = _fbb.start_table();
    PropertyBuilder {
      fbb_: _fbb,
      start_: start,
    }
  }
  #[inline]
  pub fn finish(self) -> flatbuffers::WIPOffset<Property<'a>> {
    let o = self.fbb_.end_table(self.start_);
    self.fbb_.required(o, Property::VT_KEY,"key");
    flatbuffers::WIPOffset::new(o.value())
  }
}

