  fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
    let mut ds = f.debug_struct("Property");
      ds.field("key", &self.key());
      ds.field("kind", &self.kind());
      ds.field("s", &self.s());
      ds.field("i", &self.i());
      ds.field("d", &self.d());
      ds.finish()
  }
