pub enum SnapshotOffset {}
#[derive(Copy, Clone, PartialEq)]

pub struct Snapshot<'a> {
  pub _tab: flatbuffers::Table<'a>,
}

impl<'a> flatbuffers::Follow<'a> for Snapshot<'a> {
  type Inner = Snapshot<'a>;
  #[inline]
  unsafe fn follow(buf: &'a [u8], loc: usize) -> Self::Inner {
    Self { _tab: flatbuffers::Table::new(buf, loc) }
  }
}

impl<'a> Snapshot<'a> {
  pub const VT_PROVENANCE: flatbuffers::VOffsetT = 4;
  pub const VT_SCENE: flatbuffers::VOffsetT = 6;

  #[inline]
  pub unsafe fn init_from_table(table: flatbuffers::Table<'a>) -> Self {
    Snapshot { _tab: table }
  }
  #[allow(unused_mut)]
  pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: flatbuffers::Allocator + 'bldr>(
    _fbb: &'mut_bldr mut flatbuffers::FlatBufferBuilder<'bldr, A>,
    args: &'args SnapshotArgs<'args>
  ) -> flatbuffers::WIPOffset<Snapshot<'bldr>> {
    let mut builder = SnapshotBuilder::new(_fbb);
    if let Some(x) = args.scene { builder.add_scene(x); }
    if let Some(x) = args.provenance { builder.add_provenance(x); }
    builder.finish()
  }


  #[inline]
  pub fn provenance(&self) -> Provenance<'a> {
    // Safety:
    // Created from valid Table for this object
    // which contains a valid value in this slot
    unsafe { self._tab.get::<flatbuffers::ForwardsUOffset<Provenance>>(Snapshot::VT_PROVENANCE, None).unwrap()}
  }
  #[inline]
  pub fn scene(&self) -> Option<Scene<'a>> {
    // Safety:
    // Created from valid Table for this object
    // which contains a valid value in this slot
    unsafe { self._tab.get::<flatbuffers::ForwardsUOffset<Scene>>(Snapshot::VT_SCENE, None)}
  }
}

impl flatbuffers::Verifiable for Snapshot<'_> {
  #[inline]
  fn run_verifier(
    v: &mut flatbuffers::Verifier, pos: usize
  ) -> Result<(), flatbuffers::InvalidFlatbuffer> {
    use self::flatbuffers::Verifiable;
    v.visit_table(pos)?
     .visit_field::<flatbuffers::ForwardsUOffset<Provenance>>("provenance", Self::VT_PROVENANCE, true)?
     .visit_field::<flatbuffers::ForwardsUOffset<Scene>>("scene", Self::VT_SCENE, false)?
     .finish();
    Ok(())
  }
}
pub struct SnapshotArgs<'a> {
    pub provenance: Option<flatbuffers::WIPOffset<Provenance<'a>>>,
    pub scene: Option<flatbuffers::WIPOffset<Scene<'a>>>,
}
impl<'a> Default for SnapshotArgs<'a> {
  #[inline]
  fn default() -> Self {
    SnapshotArgs {
      provenance: None, // required field
      scene: None,
    }
  }
}

pub struct SnapshotBuilder<'a: 'b, 'b, A: flatbuffers::Allocator + 'a> {
  fbb_: &'b mut flatbuffers::FlatBufferBuilder<'a, A>,
  start_: flatbuffers::WIPOffset<flatbuffers::TableUnfinishedWIPOffset>,
}
impl<'a: 'b, 'b, A: flatbuffers::Allocator + 'a> SnapshotBuilder<'a, 'b, A> {
  #[inline]
  pub fn add_provenance(&mut self, provenance: flatbuffers::WIPOffset<Provenance<'b >>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<Provenance>>(Snapshot::VT_PROVENANCE, provenance);
  }
  #[inline]
  pub fn add_scene(&mut self, scene: flatbuffers::WIPOffset<Scene<'b >>) {
    self.fbb_.push_slot_always::<flatbuffers::WIPOffset<Scene>>(Snapshot::VT_SCENE, scene);
  }
  #[inline]
  pub fn new(_fbb: &'b mut flatbuffers::FlatBufferBuilder<'a, A>) -> SnapshotBuilder<'a, 'b, A> {
    let start = _fbb.start_table();
    SnapshotBuilder {
      fbb_: _fbb,
      start_: start,
    }
  }
  #[inline]
  pub fn finish(self) -> flatbuffers::WIPOffset<Snapshot<'a>> {
    let o = self.fbb_.end_table(self.start_);
    self.fbb_.required(o, Snapshot::VT_PROVENANCE,"provenance");
    flatbuffers::WIPOffset::new(o.value())
  }
}

impl core::fmt::Debug for Snapshot<'_> {
  fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
    let mut ds = f.debug_struct("Snapshot");
      ds.field("provenance", &self.provenance());
      ds.field("scene", &self.scene());
      ds.finish()
  }
}
